update country_flag_history set image_url = '/flags/history/ie-0000.svg' where id = 2168 and iso_code = 'ie';
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('ie', '/flags/history/ie-1386.svg', '1386-01-01', '1542-06-18', 'Seigneurie d''Irlande', 'Lordship of Ireland', 'Bannière aux trois couronnes d''or sur fond bleu, emblème de la seigneurie d''Irlande détenue par les rois d''Angleterre jusqu''à la création du royaume en 1542.', 'A banner with three gold crowns on blue, the emblem of the Lordship of Ireland held by the kings of England until the kingdom was created in 1542.');
